import { createHash } from 'node:crypto'; import { readFile, writeFile } from 'node:fs/promises'; import { join } from 'node:path'; import { createExperience, initialDraft } from '../../vendor/discstudio/disc/model.ts';
const sha=b=>createHash('sha256').update(b).digest('hex');
export async function calculate({inputs,outputDir}) { const cropBytes=await readFile(inputs['parts/crop/discstudio'].files[0]),crop=JSON.parse(cropBytes);const original=await readFile(inputs['parts/source/discstudio-fixture'].files[0]),prepared=await readFile(inputs['parts/prepared/discstudio'].files[0]); if(crop.sourceClassification!=='DERIVED_FIXTURE_NOT_CREATOR_PHOTO')throw Error('Only declared derived fixture permitted.');const events=[],app=createExperience(e=>events.push(e)),hydrated=await app.hydrateSeed(initialDraft().mold),seed=app.seedAt(hydrated.address),depiction={kind:'photo',name:'derived-contact-sheet-lower-left.webp',src:`data:image/webp;base64,${prepared.toString('base64')}`};if (![seed.speed,seed.glide,seed.turn,seed.fade].every(Number.isFinite)) throw Error('Hydrated seed has no complete flight values.');const draftPhotoAddress=await app.addDraftPhoto(depiction),discAddress=await app.save({...initialDraft(),mold:hydrated.address,nickname:'Derived fixture specimen',plastic:'',weight:null,speed:seed.speed,glide:seed.glide,turn:seed.turn,fade:seed.fade},depiction),namedBagAddress=await app.createBag('Derived fixture proof bag',[discAddress]),row=app.bag().find(x=>x.address===discAddress);if(!row||!events.some(e=>e.event==='disc.save.completed')||!events.some(e=>e.event==='bag.create.completed'))throw Error('Native save/readback failed.');const inputIdentities={original:{part:'parts/source/discstudio-fixture',sha256:sha(original),contentId:inputs['parts/source/discstudio-fixture'].contentId,classification:crop.sourceClassification},crop:{part:'parts/crop/discstudio',sha256:sha(cropBytes),contentId:inputs['parts/crop/discstudio'].contentId,settings:crop},prepared:{part:'parts/prepared/discstudio',sha256:sha(prepared),contentId:inputs['parts/prepared/discstudio'].contentId}};const output=join(outputDir,'saved-discstudio.json');await writeFile(output,JSON.stringify({schema:'discstudio-nctk-save@2',inputIdentities,basePainter:'OFF',draftPhotoAddress,discAddress,shelfAddress:app.shelfAddress,bagAddress:app.bagAddress,namedBagAddress,row,events,pxcAddresses:app.pxc.entries().map(([a])=>a),appPersistenceGap:'v9 retains prepared data URL; nctk graph/receipt retains original bytes and crop settings.'},null,2)+'\n');return {files:[output],observation:{basePainter:'OFF',inputIdentities,discAddress,shelfAddress:app.shelfAddress,bagAddress:app.bagAddress,namedBagAddress,receipts:events.map(e=>e.event),appPersistenceGap:true}}; }
